<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Region</title><link rel='stylesheet' href='/assets/css/ui.css'><link rel='stylesheet' href='/assets/css/components.css'><link rel='stylesheet' href='https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css'></head><body><script src='/assets/js/ui.js'></script><script>
UX.shell('',`<div id='wrap' class='glass-card'><div class='skeleton' style='height:120px'></div></div>`);
(async()=>{const id=Number(location.pathname.split('/').pop()||0);try{const r=await UX.api('/api/map/region-detail?id='+id);wrap.innerHTML=`<div class='hero'><h2>${r.name}</h2><span class='badge'>${r.country_name}</span></div><div class='grid cols-3'><div class='glass-card'><div class='sub'>Population</div><div class='kpi'>${UX.fmt(r.population)}</div></div><div class='glass-card'><div class='sub'>Resource</div><div class='kpi'>${r.resource_type||'-'}</div></div><div class='glass-card'><div class='sub'>Total Buildings</div><div class='kpi'>${UX.fmt(r.total_score||0)}</div></div></div><h3>Infrastructure</h3><table class='table'><tr><th>Airport</th><th>Army</th><th>Hospital</th><th>Education</th><th>Port</th></tr><tr><td>${r.airport_level}</td><td>${r.army_level}</td><td>${r.hospital_level}</td><td>${r.education_level}</td><td>${r.port_level}</td></tr></table><h3>Neighbors</h3><div class='list'>${(r.neighbors||[]).map(n=>`<a class='row' href='/region/${n.id}'>${n.name}<span class='sub'>${n.country_name||''}</span></a>`).join('')||'<div class="sub">No neighbors</div>'}</div><div style='margin-top:10px'><button id='travel' class='btn'><i class='fa-solid fa-plane'></i> Travel</button> <small id='hint' class='sub'></small></div>`;travel.onclick=async()=>{try{await UX.api('/api/region/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({region_id:id,action:'travel'})});hint.textContent='Travel started';}catch(e){hint.textContent=e.message;}};}catch(e){wrap.innerHTML=`<div class='glass-card'>${e.message}</div>`;}})();
</script></body></html>
